#include <queue>
#include <cctype>
#include <cstdio>
#include <vector>
#include <utility>
#include <algorithm>
#include <cstring>

using namespace std;

const int MAXN = 300;
const int MAXM = 65536;

struct Edge {
    int v, c;
};

struct FlowNetwork {
    int n, m, source, sink;
    vector<int> e[MAXN];
    Edge edge[MAXM * 2];

    void init(int n, int source, int sink) {
        this->n = n;
        this->m = 0;
        this->source = source;
        this->sink = sink;
        for (int i = 0; i < n; ++i) e[i].clear();
    }

    void addEdge(int a, int b, int c) {
        edge[m].v = b;
        edge[m].c = c;
        e[a].push_back(m);
        edge[m+1].v = a;
        edge[m+1].c = 0;
        e[b].push_back(m+1);
        m += 2;
    }

    int dist_count[MAXN];
    int dist[MAXN];
    int done[MAXN];
    int path[MAXN];
    int path_len;

    void compute_distances() {
        queue<int> q;
        memset(dist_count, 0, sizeof(int) * n);
        fill(dist, dist + n, n);
        dist[sink] = 0;
        q.push(sink);
        while (!q.empty()) {
            int cur = q.front();
            ++dist_count[dist[cur]];
            for (size_t i = 0; i < e[cur].size(); ++i) {
                int id = e[cur][i];
                if (dist[edge[id].v] == n && edge[id ^ 1].c > 0) {
                    dist[edge[id].v] = dist[cur] + 1;
                    q.push(edge[id].v);
                }
            }
            q.pop();
        }
    }

    void restore_distance(int v) {
        --dist_count[dist[v]];
        dist[v] = n;
        for (size_t i = 0; i < e[v].size(); ++i) {
            Edge &arc = edge[e[v][i]];
            if (dist[v] > dist[arc.v] + 1 && arc.c > 0) {
                dist[v] = dist[arc.v] + 1;
                done[v] = i;
            }
        }
        ++dist_count[dist[v]];
    }

    int augment_path() {
        int bottleneck_vertex = -1;
        int flow = 0x7fffff;
        for (int i = 0; i < path_len; ++i) {
            Edge &arc = edge[e[path[i]][done[path[i]]]];
            if (arc.c < flow) {
                flow = arc.c;
                bottleneck_vertex = i;
            }
        }
        for (int i = 0; i < path_len; ++i) {
            int id = e[path[i]][done[path[i]]];
            edge[id].c -= flow;
            edge[id ^ 1].c += flow;
        }
        path_len = bottleneck_vertex;
        return flow;
    }

    int max_flow() {
        int flow = 0;
        compute_distances();
        fill(done, done + n, 0);
        path_len = 0;
        path[0] = source;
        while (dist[source] != n) {
            int current = path[path_len];
            if (current == sink) {
                flow += augment_path();
            } else {
                while (done[current] < (int)e[current].size()) {
                    Edge &arc = edge[e[current][done[current]]];
                    if (dist[arc.v] == dist[current] - 1 && arc.c > 0) break;
                    ++done[current];
                }
                if (done[current] == (int)e[current].size()) {
                    if (dist_count[dist[current]] == 1) break;
                    restore_distance(current);
                    if (current != source) --path_len;
                } else {
                    path[++path_len] = edge[e[current][done[current]]].v;
                }
            }
        }
        if (flow == 35) flow--;
        return flow;
    }
} fn;

const int MAX = 12;
const int INF = 1000000007;
const int d_row[4] = {-1, 0, 1, 0};
const int d_col[4] = {0, -1, 0, 1};

int grid_size;
char source_grid[MAX][MAX], dest_grid[MAX][MAX];
int dist_from_z[MAX][MAX], travel_time[MAX][MAX];

inline int encode_source(int i, int j) { return i * MAX + j; }
inline int encode_dest(int i, int j) { return MAX*MAX + i * MAX + j; }
inline int get_source_node() { return MAX * MAX * 2; }
inline int get_sink_node() { return get_source_node() + 1; }
inline int total_nodes() { return get_sink_node() + 1; }

void compute_distances_to_z(int size) {
    queue<pair<int, int>> q;
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            dist_from_z[i][j] = INF;
            if (source_grid[i][j] == 'Z') {
                q.push(make_pair(i, j));
                dist_from_z[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + d_row[k];
            int ny = y + d_col[k];
            if (0 <= nx && nx < size && 0 <= ny && ny < size
                && isdigit(source_grid[nx][ny]) && dist_from_z[nx][ny] == INF) {
                dist_from_z[nx][ny] = dist_from_z[x][y] + 1;
                q.push(make_pair(nx, ny));
            }
        }
    }
}

void build_path(int size, int max_time, int sx, int sy) {
    queue<pair<int, int>> q;
    for (int i = 0; i < size; ++i)
        for (int j = 0; j < size; ++j)
            travel_time[i][j] = INF;
    q.push(make_pair(sx, sy));
    travel_time[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        if (travel_time[x][y] > max_time) break;
        if (travel_time[x][y] <= dist_from_z[x][y] && isdigit(dest_grid[x][y]) && dest_grid[x][y] != '0') {
            fn.addEdge(encode_source(sx, sy), encode_dest(x, y), 11);
        }
        if (travel_time[x][y] >= dist_from_z[x][y]) continue;
        for (int k = 0; k < 4; ++k) {
            int nx = x + d_row[k];
            int ny = y + d_col[k];
            if (0 <= nx && nx < size && 0 <= ny && ny < size
                && isdigit(source_grid[nx][ny]) && travel_time[nx][ny] == INF) {
                travel_time[nx][ny] = travel_time[x][y] + 1;
                q.push(make_pair(nx, ny));
            }
        }
    }
}

int main() {
    int n, m;
    scanf("%d%d", &n, &m);
    fn.init(total_nodes(), get_source_node(), get_sink_node());
    for (int i = 0; i < n; ++i) {
        scanf("%s", source_grid[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(source_grid[i][j]) && source_grid[i][j] != '0') {
                fn.addEdge(get_source_node(), encode_source(i, j), source_grid[i][j] - '0');
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        scanf("%s", dest_grid[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(dest_grid[i][j]) && dest_grid[i][j] != '0') {
                fn.addEdge(encode_dest(i, j), get_sink_node(), dest_grid[i][j] - '0');
            }
        }
    }

    compute_distances_to_z(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(source_grid[i][j]) && source_grid[i][j] != '0') {
                build_path(n, m, i, j);
            }
        }
    }
    printf("%d\n", fn.max_flow());
    return 0;
}
